1	package org.springframework.samples.petclinic.rest.function.owner;
2	
3	import java.util.HashSet;
4	import java.util.Set;
5	
6	import net.officefloor.plugin.variable.Val;
7	import org.springframework.samples.petclinic.model.Owner;
8	import org.springframework.samples.petclinic.repository.OwnerRepository;
9	
10	/**
11	 * Assigns the owner's {@code memberId}, the unified identity {@code '<REGION><FY><HASH8><CHK>'}
12	 * where REGION is the region code derived from the postcode (falling back to the city, then
13	 * {@code 'UNKNOWN'}), FY the two-digit fiscal year of the registrationDate, HASH8 the first 8
14	 * upper-case hex characters of SHA-256 over {@code normalizedTelephone + lastName} and CHK a single
15	 * Luhn check digit over the digits of {@code <REGION><FY><HASH8>} (e.g. {@code 'NSW271A2B3C4D5'}).
16	 * See {@link MemberId}.
17	 *
18	 * <p>The base memberId is a pure function of the owner's already-normalized telephone, last name,
19	 * postcode, city and registrationDate. When that base collides with an existing owner's
20	 * {@code memberId}, this step de-duplicates it by appending {@code '-<n>'} with the smallest
21	 * {@code n >= 2} that makes the result unique across all persisted owners. Runs after
22	 * {@link BuildOwner} has mapped the request onto the entity (telephone already normalized to E.164
23	 * by {@link ValidateOwnerFields}) and {@link DefaultRegistrationDate} has resolved the date, and
24	 * before {@link SaveOwner}, within the same write transaction so the uniqueness check and the insert
25	 * see one consistent view.
26	 */
27	public class AssignMemberId {
28	
29	    public void service(@Val Owner owner, OwnerRepository ownerRepository) {
30	        String base = MemberId.of(owner.getTelephone(), owner.getLastName(), owner.getPostcode(),
31	                owner.getCity(), owner.getRegistrationDate());
32	
33	        Set<String> taken = new HashSet<>();
34	        for (Owner existing : ownerRepository.findAll()) {
35	            if (existing != owner && existing.getMemberId() != null) {
36	                taken.add(existing.getMemberId());
37	            }
38	        }
39	
40	        String memberId = base;
41	        for (int n = 2; taken.contains(memberId); n++) {
42	            memberId = base + "-" + n;
43	        }
44	        owner.setMemberId(memberId);
45	    }
46	}
